// public/sw.js
self.addEventListener('fetch', (event) => {
  const { request } = event; const url = new URL(request.url);
  if (request.method !== 'GET') return;            // never cache POSTs
  if (url.origin !== self.location.origin) {
    if (isApiRequest(url)) { event.respondWith(networkFirstWithApiCache(request)); return; }
    event.respondWith(networkOnly(request)); return;
  }
  // ... same-origin strategies
});
function isApiRequest(url) {
  const apiHosts = ['generativelanguage.googleapis.com',
                    'integrate.api.nvidia.com',
                    'api.openweathermap.org'];
  return apiHosts.some((host) => url.hostname.includes(host));
}

// services/persistence.ts
private getItem<T>(key: string, defaultValue: T): T {
  try {
    const item = localStorage.getItem(key);
    return item ? JSON.parse(item) : defaultValue;
  } catch (error) {
    console.error(`[DB Read Error] Key: ${key}`, error);
    return defaultValue;
  }
}
private setItem<T>(key: string, value: T): boolean {
  try { localStorage.setItem(key, JSON.stringify(value)); return true; }
  catch (error) { console.error(`[DB Write Error] Key: ${key}`, error); return false; }
}

// contexts/FarmContext.tsx — navigate() allow-list
const VALID_TABS = new Set(Object.values(NavigationTab));
const navigate = useCallback((view: NavigationTab) => {
  if (!VALID_TABS.has(view)) {
    console.warn(`[AgriFlow] Invalid navigation target: "${view}"`);
    view = NavigationTab.DASHBOARD;
  }
  setCurrentView(view);
  window.history.pushState(null, '', `#${VIEW_HASH[view] || 'dashboard'}`);
}, []);

